import{_ as o,l as n,o as a,c as i,v as r,p as s,x as l,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"递归定理","description":"","frontmatter":{"title":"递归定理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/recursion-theorem.md","filePath":"cs/recursion-theorem.md","lastUpdated":1789023840000}'),h={name:"cs/recursion-theorem.md"};function m(_,e,E,u,A,g){const t=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=r('<h1 id="递归定理" tabindex="-1">递归定理 <a class="header-anchor" href="#递归定理" aria-label="Permalink to &quot;递归定理&quot;">​</a></h1><div class="epigraph"><p>任何可计算变换 $t$，都有机器 $M$ 使 $M$ 与 $t(\\langle M\\rangle)$ 计算同一函数；程序可以获得自身的文本。</p><footer>—— 据 Kleene；Sipser 整理</footer></div><p>上一课<a href="/cs/rice-theorem">Rice</a>谈外延性质，机器看不到自己的编码——除非我们另给。缺口是<strong>Kleene 递归定理</strong>（不动点）：存在自指程序。病毒「把自身复制进输出」、构造「打印自己的源」都落在这里；后课 Kolmogorov 也要用最短描述的自指。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可计算函数 \\(t\\) 把编码变成编码。递归定理：存在 \\(e\\)，\\(\\{e\\}=\\{t(e)\\}\\)（同一部分函数）。构造：先做「给定 \\(w\\)，算出 \\(\\langle P_w\\rangle\\) 再跑 \\(t(\\langle P_w\\rangle)\\) 于输入」，其中 \\(P_w\\) 是「先写出 \\(w\\) 再做……」的机器。对角地喂入自身描述。本课要存在性与用法，不把组合子 \\(Y\\) 提前（那是 λ 课）。</p><p>没有定理时，TM 的 \\(\\delta\\) 表里写不进「本机的 \\(\\langle M\\rangle\\)」——表是有限的，编码依赖于整张表。递归定理说：先允许一个变换假定「编码会填进来」，再保证有填法一致。应用：构造 \\(M\\) 在输入 \\(w\\) 上检查 \\(w=\\langle M\\rangle\\) 之类的机器，证明仍合法。</p><h3 id="不是数学归纳法" tabindex="-1">不是数学归纳法 <a class="header-anchor" href="#不是数学归纳法" aria-label="Permalink to &quot;不是数学归纳法&quot;">​</a></h3><p>名字里的 recursion 是自指，不是「对 \\(n\\) 归纳」。程序递归调用自身是其推论：调用时编码已知。</p><p><span class="marginnote">Kleene 第二递归定理。Sipser 用「获得自身描述」的应用版。Quine（打印自身的程序）是同一现象的玩具。固定点在 λ 课用 \\(Y\\)，对象换成项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>应用：存在 \\(M\\) 输出 \\(\\langle M\\rangle\\) 然后停（Quine）。不要用定理声称「一切自修改代码都不可分析」——Rice 已经管语义；这里管的是描述的存在。</p>',11)),(a(),s(c,null,{default:l(()=>[d(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%8F%AF%E8%AE%A1%E7%AE%97%20t%22%5D%20--%3E%20FP%5B%22%E5%AD%98%E5%9C%A8%20M%20%E2%89%A1%20t%E2%9F%A8M%E2%9F%A9%22%5D%0A%20%20FP%20--%3E%20SELF%5B%22%E7%A8%8B%E5%BA%8F%E5%BE%97%E5%88%B0%E8%87%AA%E8%BA%AB%E6%96%87%E6%9C%AC%22%5D%0A%20%20SELF%20--%3E%20LATER%5B%22Kolmogorov%20%2F%20%E7%97%85%E6%AF%92%E5%A4%8D%E5%88%B6%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了自指，才能写「最短程序」时出现的循环论证：描述「比这个还短的程序不存在」会指涉自身长度。下一课 Kolmogorov 复杂度不可计算，递归定理提供合法性。也可用来给 Rice 另一种证明，本课不换证明。</p><p>与停机的关系：自指程序仍是普通 TM，停机问题并不因此可解。</p><p>构造病毒「把自身写入文件」在模型里合法，不增加计算类。证明停机时不能假设「程序不知道自己的源」——它可以知道。Kolmogorov 课用自指封住「最短不可压缩串」的描述。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 \\(s\\)-\\(m\\)-\\(n\\) 定理的全部细节，不写组合逻辑。不讨论生物学或实际恶意软件。后课默认：需要「机器带着自己的源」时，递归定理保证存在。下一课把最短描述当成复杂度。</p><p>自指给出的 \\(M\\) 仍是普通图灵机，不扩大 RE。后课最短描述的悖论式构造因此合法：描述可以谈论「本串的 \\(K\\)」。λ 侧的对应物是 \\(Y\\)，不是本课对象。</p><p>上一课留下的缺口在本课收口；「递归定理」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>任意可计算 \\(t\\) 有不动点机器：\\(M\\) 与 \\(t(\\langle M\\rangle)\\) 同函数。</li><li>程序可以合法地引用自身编码。</li><li>自指不增加可计算类，只增加构造手法。</li><li>后课 \\(K(x)\\) 的自指描述靠本课才合法。</li><li>出处：Kleene；Sipser。</li></ul>',10))])}const P=o(h,[["render",m]]);export{T as __pageData,P as default};
